import { defineGroup, example, flag, integer, list, text } from "../define";

export const authGroup = defineGroup({
  name: "auth",
  title: "Authentication",
  vars: {
    secret: text({
      env: "BETTER_AUTH_SECRET",
      description:
        "Session signing secret, at least 32 characters (generated by setup).",
      secret: true,
      requiredInProduction: ["api"],
      minLengthInProduction: 32,
      example: example.generated(),
    }),
    appEnv: text({
      env: "APP_ENV",
      description: "Older alias of NODE_ENV read by the auth layer.",
      hidden: true,
    }),
    devAllowedHosts: list({
      env: "AUTH_DEV_ALLOWED_HOSTS",
      description:
        "Development only: extra hostnames (tunnels, LAN) accepted by auth.",
      example: example.commented(""),
    }),
    passkeyRpId: text({
      env: "PASSKEY_RP_ID",
      description: "Passkeys: relying-party id (defaults derive from APP_URL).",
      example: example.commented(""),
    }),
    passkeyExtraOrigins: list({
      env: "PASSKEY_EXTRA_ORIGINS",
      description: "Passkeys: extra origins (comma-separated).",
      example: example.commented(""),
    }),
    publicSignupEnabled: flag({
      env: "PUBLIC_SIGNUP_ENABLED",
      description: "Self-service lab sign-up (corporate e-mail domains only).",
      default: false,
      example: example.commented("false"),
    }),
    portalServiceUserId: text({
      env: "PORTAL_SERVICE_USER_ID",
      description:
        "Service account that owns client-portal organizations (created by the seed / init).",
      requiredInProduction: ["api"],
      example: example.active("portal-service"),
    }),
    portalInvitationExpiresIn: integer({
      env: "PORTAL_INVITATION_EXPIRES_IN",
      description:
        "Seconds a client-portal invitation stays valid. An unusable value means the default.",
      min: 1,
      tolerant: true,
      example: example.commented("604800"),
    }),
    quoteApprovalCodePepper: text({
      env: "QUOTE_APPROVAL_CODE_PEPPER",
      description:
        "Pepper for public quote approval-code HMACs (random string). Rotating it orphans outstanding codes.",
      secret: true,
      requiredInProduction: ["api"],
      example: example.generated(),
    }),
  },
});
